# ---------------- BANQUES DE QUIZ ----------------
# Toutes les réponses sont produites directement depuis les tables ci-dessus.
# Chaque code possède au moins 104 questions. Le Morse couvre aussi les
# chiffres et signes présents dans sa table, pas seulement les 26 lettres.

def character_kind(char):
    if char.isalpha():
        return "lettre"
    if char.isdigit():
        return "chiffre"
    return "signe"


def build_letter_quiz(mapping, display, label="lettre"):
    bank = []
    characters = list(mapping.keys())

    for char in characters:
        code = display(mapping[char])
        other_chars = [item for item in characters if item != char]
        wrong_chars = random.sample(other_chars, min(3, len(other_chars)))
        wrong_codes = [
            display(mapping[item])
            for item in random.sample(other_chars, min(3, len(other_chars)))
        ]

        # Quatre formulations pédagogiques : émission et réception.
        questions = [
            {
                "question": f"Quel code faut-il utiliser pour transmettre {label} « {char} » ?",
                "options": [code] + wrong_codes,
                "answer": code,
                "explanation": f"Dans la table de référence, {char} correspond à {code}.",
            },
            {
                "question": f"Tu reçois le code « {code} ». Quel caractère dois-tu noter ?",
                "options": [char] + wrong_chars,
                "answer": char,
                "explanation": f"Le code {code} représente {char} dans la table de référence.",
            },
            {
                "question": f"Pour envoyer « {char} », quelle proposition est exacte ?",
                "options": [code] + random.sample(
                    [display(mapping[item]) for item in other_chars],
                    min(3, len(other_chars))
                ),
                "answer": code,
                "explanation": f"Le codage exact de {char} est {code}.",
            },
            {
                "question": f"Lors du décodage, le signal « {code} » correspond à :",
                "options": [char] + random.sample(
                    other_chars, min(3, len(other_chars))
                ),
                "answer": char,
                "explanation": f"En décodage, {code} se lit {char}.",
            },
        ]

        for item in questions:
            # Mélange les choix sans changer la réponse correcte.
            random.shuffle(item["options"])
            bank.append(item)

    return bank


