total_questions = len(question_bank)

st.caption(
    f"Banque : {total_questions} questions. "
    "Les questions et les choix sont mélangés à chaque nouvelle série."
)

if position >= total_questions:
    st.success(
        f"Série terminée ! Score : {scores.get(quiz_choice, 0)} / {total_questions}."
    )
    if st.button("🎲 Recommencer avec de nouvelles questions", key="fauco_restart_finished"):
        new_order = list(range(total_questions))
        random.shuffle(new_order)
        orders[quiz_choice] = new_order
        positions[quiz_choice] = 0
        scores[quiz_choice] = 0
        validated[quiz_choice] = {}
        st.rerun()
else:
    question_index = orders[quiz_choice][position]
    question = question_bank[question_index]
    question_key = f"{quiz_choice}_{position}"
    already_validated = question_key in validated[quiz_choice]

    st.progress(position / total_questions)
    st.caption(
        f"Question {position + 1} / {total_questions} "
        f"• Score : {scores.get(quiz_choice, 0)}"
    )
    st.write(f"**{question['question']}**")

    answer = st.radio(
        "Choisis une seule réponse :",
        question["options"],
        key=f"fauco_answer_{quiz_choice}_{position}",
        disabled=already_validated,
    )

    if not already_validated:
        if st.button("Valider ma réponse", key=f"fauco_validate_{quiz_choice}_{position}"):
            is_correct = answer == question["answer"]
            validated[quiz_choice][question_key] = {
                "correct": is_correct,
                "answer": question["answer"],
                "explanation": question["explanation"],
            }
            if is_correct:
                scores[quiz_choice] = scores.get(quiz_choice, 0) + 1
            st.rerun()
    else:
        result = validated[quiz_choice][question_key]
        if result["correct"]:
            st.success("Bonne réponse !")
        else:
            st.error(f"Réponse incorrecte. La bonne réponse était : {result['answer']}")
        st.info(result["explanation"])

        if st.button("➡️ Question suivante", key=f"fauco_next_{quiz_choice}_{position}"):
            positions[quiz_choice] = position + 1
            st.rerun()

    st.metric("⭐ Score de cette série", scores.get(quiz_choice, 0))
    st.caption(
        f"Réponses validées : {len(validated[quiz_choice])} / {total_questions}"
    )

